// Validiert Score (1–10) und sanitisiert die Submission-ID.
// Fehlerhafte Parameter werden sofort mit einer Fehlerseite beantwortet.

const query  = $('Webhook').item.json.query || {};
const rawId  = String(query.id    || '').trim();
const rawScore = String(query.score || '').trim();

// Submission-ID: nur SeaTable-Row-ID-Zeichen erlaubt
const id = rawId.replace(/[^A-Za-z0-9_-]/g, '');

// Score: muss ganze Zahl 1–10 sein
const score = parseInt(rawScore, 10);
const valid = id.length > 0 && Number.isInteger(score) && score >= 1 && score <= 10;

if (!valid) {
  return [{
    json: {
      valid: false,
      error: !id ? 'missing_id' : 'invalid_score',
      id: '',
      score: 0
    }
  }];
}

return [{ json: { valid: true, id, score } }];

